/// Returns an error if the stream is truncated (no FINAL tag received) or
/// if any chunk fails authentication (ciphertext was modified or key is wrong).
fn decrypt_file(
    input_path: &Path,
    output_path: &Path,
    key: &kdf::Key,
) -> io::Result<()> {
    let mut reader = BufReader::with_capacity(CHUNK_SIZE * 2, File::open(input_path)?);
    let mut writer = BufWriter::new(File::create(output_path)?);

    // Read the header.
    let mut header_bytes = [0u8; HEADER_SIZE];
    reader.read_exact(&mut header_bytes)?;
    let header = secretstream::Header(header_bytes);

    let mut dec_stream = Stream::init_pull(&header, key).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "invalid header or key mismatch",
        )
    })?;

    // Encrypted chunks are plaintext_len + ABYTES (17 bytes overhead).
    let enc_chunk_size = CHUNK_SIZE + secretstream::ABYTES;
    let mut enc_buf = vec![0u8; enc_chunk_size];

    loop {
        let n = reader.read(&mut enc_buf)?;
        if n == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "stream ended without FINAL tag — file may be truncated or tampered",
            ));
        }

        let (plaintext, tag) = dec_stream.pull(&enc_buf[..n]).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "authentication failed — ciphertext was modified or key is wrong",
            )
        })?;

        writer.write_all(&plaintext)?;

        if tag == secretstream::Tag::Final {
            break;
        }
    }

    writer.flush()?;
    Ok(())
}

fn generate_master_key() -> kdf::Key {
    let mut key_bytes = [0u8; 32];
    randombytes::into(&mut key_bytes);
    kdf::Key(key_bytes)
}

fn print_usage() {
    eprintln!("Usage:");
    eprintln!("  filecrypt genkey <output-key-file>");
    eprintln!("  filecrypt encrypt <input> <output> <key-file>");
    eprintln!("  filecrypt decrypt <input> <output> <key-file>");
}

